package sfz.sql.l10.demo

import com.zaxxer.hikari.HikariConfig
import com.zaxxer.hikari.HikariDataSource

/**
 * Lesson sql-10, Try it 1: what a connection costs, what a query costs, what a pool saves, and
 * how a big result arrives: all at once (pgJDBC's default) or in slices through a cursor.
 *
 *   ./gradlew :sql:demo -Pmain=sfz.sql.l10.demo.ConnectionCostKt      (from the labs folder)
 */
fun main() {
    println("server: ${Db.url}")

    // 1. ten new connections, one after the other: each is a TCP connection, a login and a new server process
    val pids = mutableListOf<Int>()
    var connectTrips = 0
    val connectMs = (1..10).map {
        val t = System.nanoTime()
        val (conn, trips) = RoundTrips.count { Db.counted() }
        connectTrips = trips
        conn.use { c ->
            val elapsed = ms(System.nanoTime() - t)
            c.createStatement().use { st -> st.executeQuery("SELECT pg_backend_pid()").use { rs -> rs.next(); pids += rs.getInt(1) } }
            elapsed
        }
    }
    println("open a connection:            median ${median(connectMs)}   ($connectTrips round trips each)")
    println("  ten connections, ten server processes: ${pids.joinToString(" ")}")

    // 2. 1,000 tiny queries on one open connection: each is one round trip
    Db.counted().use { c ->
        c.prepareStatement("SELECT 1").use { ps ->
            repeat(200) { ps.executeQuery().close() }               // warm up
            val (queryMs, trips) = RoundTrips.count {
                (1..1000).map {
                    val t = System.nanoTime()
                    ps.executeQuery().use { it.next() }
                    ms(System.nanoTime() - t)
                }
            }
            println("SELECT 1 on an open one:      median ${median(queryMs)}   ($trips round trips for 1,000 queries)")
        }
    }

    // 3. the same through a pool of 4: borrow, query, give back
    HikariDataSource(HikariConfig().apply {
        jdbcUrl = Db.url
        username = Db.USER
        password = Db.PASSWORD
        maximumPoolSize = 4
        poolName = "demo"
    }).use { pool ->
        repeat(200) { pool.connection.use { c -> c.createStatement().use { it.execute("SELECT 1") } } }
        val borrowMs = mutableListOf<Double>()
        val pooledMs = (1..1000).map {
            val t = System.nanoTime()
            pool.connection.use { c ->                               // close() hands it back, open
                borrowMs += ms(System.nanoTime() - t)
                c.prepareStatement("SELECT 1").use { ps -> ps.executeQuery().use { it.next() } }
            }
            ms(System.nanoTime() - t)
        }
        println("borrow from a pool of 4:      median ${median(borrowMs)}")
        println("borrow + SELECT 1 + return:   median ${median(pooledMs)}")
    }

    // 4. one million rows, read with fetchSize 0 (everything in the first answer) and 10,000 (a cursor)
    Db.counted().use { c ->
        c.autoCommit = false                                         // a cursor lives inside a transaction
        for (size in listOf(0, 10_000)) {
            c.prepareStatement("SELECT g, md5(g::text) FROM generate_series(1, 1000000) AS g").use { ps ->
                ps.fetchSize = size
                val before = usedHeapMb()
                val (heldMb, trips) = RoundTrips.count {
                    ps.executeQuery().use { rs ->
                        rs.next()                                    // the first row is here: what does the JVM hold?
                        val held = usedHeapMb() - before
                        while (rs.next()) { }
                        held
                    }
                }
                println("1,000,000 rows, fetchSize %-6d heap held at the first row: %4d MB, round trips: %d".format(size, heldMb, trips))
            }
        }
        c.rollback()
    }
}

private fun usedHeapMb(): Long {
    System.gc()
    val rt = Runtime.getRuntime()
    return (rt.totalMemory() - rt.freeMemory()) / (1024 * 1024)
}

package sfz.sql.l10.demo

import com.zaxxer.hikari.HikariConfig
import com.zaxxer.hikari.HikariDataSource
import java.sql.Connection
import java.sql.SQLTransientConnectionException
import java.util.concurrent.Executors

/**
 * Lesson sql-10, Try it 2: ten requests share a pool of four connections, then a leak drains it.
 *
 *   ./gradlew :sql:demo -Pmain=sfz.sql.l10.demo.PoolWaitKt      (from the labs folder)
 */
fun main() {
    println("server: ${Db.url}")
    val config = HikariConfig().apply {
        jdbcUrl = Db.url
        username = Db.USER
        password = Db.PASSWORD
        poolName = "payments"
        maximumPoolSize = 4
        minimumIdle = 4
        connectionTimeout = 1_000               // a borrower waits at most 1 s
        leakDetectionThreshold = 2_000          // log a connection held for more than 2 s
    }
    HikariDataSource(config).use { pool ->
        while (pool.hikariPoolMXBean.idleConnections < 4) Thread.sleep(20)   // the pool opens its 4

        // 1. ten requests at once, each holding a connection for a 300 ms query
        val start = System.nanoTime()
        Executors.newVirtualThreadPerTaskExecutor().use { threads ->
            val results = (1..10).map { n ->
                threads.submit<Pair<Int, Double>> {
                    val asked = System.nanoTime()
                    pool.connection.use { c ->
                        val waited = ms(System.nanoTime() - asked)
                        c.createStatement().use { it.execute("SELECT pg_sleep(0.3)") }
                        n to waited
                    }
                }
            }
            results.map { it.get() }.sortedBy { it.second }
                .forEach { (n, waited) -> println("request %2d waited %4.0f ms for a connection".format(n, waited)) }
        }
        println("all ten done after %.0f ms".format(ms(System.nanoTime() - start)))

        // 2. a leak: code that borrows and never calls close(), four times
        val leaked = mutableListOf<Connection>()
        repeat(4) { leaked += pool.connection }
        println("leaked 4 connections; the pool says ${pool.hikariPoolMXBean.activeConnections} active, ${pool.hikariPoolMXBean.idleConnections} idle")
        val asked = System.nanoTime()
        try {
            pool.connection.use { }
        } catch (e: SQLTransientConnectionException) {
            println("the next borrower, after %.0f ms: %s".format(ms(System.nanoTime() - asked), e.message))
        }
        Thread.sleep(2_500)                     // past leakDetectionThreshold: Hikari logs each leak
        leaked.forEach { it.close() }
    }
}

package sfz.sql.l10.demo

import java.sql.Connection
import java.sql.Statement

/**
 * Lesson sql-10, Try it 3: a value pasted into SQL versus a value sent as a parameter, what
 * comes back as a "generated key", and when pgJDBC starts preparing on the server.
 *
 *   ./gradlew :sql:demo -Pmain=sfz.sql.l10.demo.InjectionKt      (from the labs folder)
 */
fun main() {
    println("server: ${Db.url}")
    val name = "' OR '1'='1"
    Db.connect().use { conn ->
        conn.autoCommit = false                                       // everything below is rolled back

        // 1. the name pasted into the SQL text
        val pasted = "SELECT merchant_id, name FROM merchants WHERE name = '$name'"
        println("pasted SQL: $pasted")
        conn.createStatement().use { st -> st.executeQuery(pasted).use { rs -> println("  rows: ${count(rs)}") } }

        // 2. the same name as a parameter
        conn.prepareStatement("SELECT merchant_id, name FROM merchants WHERE name = ?").use { ps ->
            ps.setString(1, name)
            ps.executeQuery().use { rs -> println("parameter:  SELECT ... WHERE name = ?   with ? = $name\n  rows: ${count(rs)}") }
        }

        // 3. generated keys: the flag, then a named column
        val insert = "INSERT INTO merchants (name, mcc, country_code) VALUES (?, '5812', 'IE')"
        conn.prepareStatement(insert, Statement.RETURN_GENERATED_KEYS).use { ps ->
            ps.setString(1, "Copper Kettle")
            ps.executeUpdate()
            ps.generatedKeys.use { keys -> println("RETURN_GENERATED_KEYS gives back: ${columns(keys)}") }
        }
        conn.prepareStatement(insert, arrayOf("merchant_id")).use { ps ->
            ps.setString(1, "Mama's Kitchen")                         // the apostrophe is just a character
            ps.executeUpdate()
            ps.generatedKeys.use { keys -> keys.next(); println("arrayOf(\"merchant_id\") gives back: merchant_id = ${keys.getLong(1)}") }
        }

        // 4. the same PreparedStatement run six times: from the fifth, it is prepared on the server
        conn.prepareStatement("SELECT name FROM merchants WHERE merchant_id = ?").use { ps ->
            for (run in 1..6) {
                ps.setLong(1, run.toLong())
                ps.executeQuery().close()
                println("run $run: server-side prepared statements on this connection = ${prepared(conn)}")
            }
        }
        conn.rollback()
    }
}

private fun count(rs: java.sql.ResultSet): Int {
    var n = 0
    while (rs.next()) n++
    return n
}

private fun columns(rs: java.sql.ResultSet): String =
    (1..rs.metaData.columnCount).joinToString(", ") { rs.metaData.getColumnName(it) }

private fun prepared(conn: Connection): String = conn.createStatement().use { st ->
    st.executeQuery("SELECT name FROM pg_prepared_statements ORDER BY name").use { rs ->
        buildList { while (rs.next()) add(rs.getString(1)) }.ifEmpty { listOf("none") }.joinToString()
    }
}

package sfz.sql.l10.demo

import java.sql.Connection
import java.sql.Timestamp
import java.time.Instant

/**
 * Lesson sql-10, Try it 4: the same 2,000 rows inserted four ways, then the N+1 dashboard and
 * its one-query version. For each, the round trips (a counting socket), the statements the
 * server ran (pg_stat_statements) and the time, which depends on your machine.
 *
 *   ./gradlew :sql:demo -Pmain=sfz.sql.l10.demo.BatchingKt      (from the labs folder)
 */
private const val ROWS = 2_000

fun main() {
    println("server: ${Db.url}")
    println("%-34s %12s %11s %10s".format("2,000 rows into payment_import", "round trips", "statements", "time"))
    insertWay("loop, autocommit") { c -> c.autoCommit = true; loop(c) }
    insertWay("loop, one transaction") { c -> loop(c); c.commit() }
    insertWay("addBatch, one executeBatch") { c -> batch(c); c.commit() }
    insertWay("addBatch + reWriteBatchedInserts", mapOf("reWriteBatchedInserts" to "true")) { c -> batch(c); c.commit() }

    println()
    println("%-34s %12s %11s %10s".format("latest payment of each merchant", "round trips", "statements", "time"))
    Db.counted().use { c ->
        repeat(3) { nPlusOne(c); oneQuery(c) }                        // warm up both
        report("N+1: merchants, then one per merchant", "SELECT") { nPlusOne(c) }
        report("one query with LEFT JOIN LATERAL", "SELECT") { oneQuery(c) }
    }
}

private fun insertWay(label: String, props: Map<String, String> = emptyMap(), work: (Connection) -> Unit) {
    Db.counted(props).use { c ->
        c.createStatement().use {
            it.execute("CREATE TEMP TABLE payment_import (card_id bigint, merchant_id bigint, amount_minor bigint, status text, created_at timestamptz)")
        }
        c.autoCommit = false
        report(label, "INSERT INTO payment_import") { work(c) }
    }
}

private fun report(label: String, statementPrefix: String, work: () -> Unit) {
    Db.connect().use { s -> s.createStatement().use { it.execute("SELECT pg_stat_statements_reset()") } }
    val t = System.nanoTime()
    val (_, trips) = RoundTrips.count(work)
    val elapsed = ms(System.nanoTime() - t)
    val statements = Db.connect().use { s ->
        s.prepareStatement("SELECT coalesce(sum(calls), 0) FROM pg_stat_statements WHERE query ILIKE ? || '%' AND query NOT ILIKE '%pg_stat_statements%'").use { ps ->
            ps.setString(1, statementPrefix)
            ps.executeQuery().use { it.next(); it.getLong(1) }
        }
    }
    println("%-34s %12d %11d %7.0f ms".format(label, trips, statements, elapsed))
}

private const val INSERT = "INSERT INTO payment_import (card_id, merchant_id, amount_minor, status, created_at) VALUES (?, ?, ?, ?, ?)"
private val t0 = Instant.parse("2026-07-01T00:00:00Z")

private fun loop(c: Connection) = c.prepareStatement(INSERT).use { ps ->
    for (i in 1..ROWS) {
        bind(ps, i)
        ps.executeUpdate()                                            // send one row, wait for "INSERT 0 1"
    }
}

private fun batch(c: Connection) = c.prepareStatement(INSERT).use { ps ->
    for (i in 1..ROWS) {
        bind(ps, i)
        ps.addBatch()                                                 // queue it in the driver
    }
    ps.executeBatch()                                                 // send the queue
}

private fun bind(ps: java.sql.PreparedStatement, i: Int) {
    ps.setLong(1, 1L + i % 14)
    ps.setLong(2, 1L + i % 8)
    ps.setLong(3, 100L + i)
    ps.setString(4, "succeeded")
    ps.setTimestamp(5, Timestamp.from(t0.plusSeconds(i.toLong())))
}

private const val LATEST = "SELECT payment_id, amount_minor FROM payments WHERE merchant_id = ? AND status = 'succeeded' ORDER BY created_at DESC, payment_id DESC LIMIT 1"

private fun nPlusOne(c: Connection): Int {
    val ids = c.prepareStatement("SELECT merchant_id FROM merchants ORDER BY merchant_id").use { ps ->
        ps.executeQuery().use { rs -> buildList { while (rs.next()) add(rs.getLong(1)) } }
    }
    return c.prepareStatement(LATEST).use { ps ->
        ids.count { id ->
            ps.setLong(1, id)
            ps.executeQuery().use { it.next() }                       // one round trip per merchant
        }
    }
}

private fun oneQuery(c: Connection): Int = c.prepareStatement(
    """
    SELECT m.merchant_id, p.payment_id, p.amount_minor
    FROM merchants m
    LEFT JOIN LATERAL (
        SELECT payment_id, amount_minor FROM payments
        WHERE merchant_id = m.merchant_id AND status = 'succeeded'
        ORDER BY created_at DESC, payment_id DESC LIMIT 1
    ) p ON true
    ORDER BY m.merchant_id
    """,
).use { ps -> ps.executeQuery().use { rs -> var n = 0; while (rs.next()) n++; n } }

package sfz.sql.l10.demo

import org.flywaydb.core.Flyway
import org.flywaydb.core.api.FlywayException

/**
 * Lesson sql-10, Try it 5: Flyway applies the migrations in src/demo/resources/sfz/sql/l10/demo/migration
 * to schema l10_demo of database course, and records them in l10_demo.flyway_schema_history.
 *
 *   ./gradlew :sql:demo -Pmain=sfz.sql.l10.demo.MigrateKt      (from the labs folder)
 *
 * Start over with DROP SCHEMA l10_demo CASCADE; in psql.
 */
fun main() {
    println("server: ${Db.url}")
    val flyway = Flyway.configure()
        .dataSource(Db.url, Db.USER, Db.PASSWORD)
        .schemas("l10_demo")                                   // created if missing; holds the history table
        .locations("classpath:sfz/sql/l10/demo/migration")
        .load()

    fun info(title: String) {
        println(title)
        flyway.info().all().forEach { m -> println("  version %-4s %-28s %s".format(m.version ?: "-", m.description, m.state)) }
    }

    info("before migrate:")
    try {
        val result = flyway.migrate()
        println("migrate: ${result.migrationsExecuted} migration(s) applied, schema now at version ${result.targetSchemaVersion ?: result.initialSchemaVersion}")
    } catch (e: FlywayException) {
        println("migrate refused: ${e.message?.lineSequence()?.filter { it.isNotBlank() }?.take(4)?.joinToString("\n  ")}")
        return
    }
    info("after migrate:")
}

