// 1. the pool, created once for the whole service
val pool = HikariDataSource(HikariConfig().apply {
    jdbcUrl = "jdbc:postgresql://db:5432/payments"
    username = "importer"
    password = System.getenv("DB_PASSWORD")
    maximumPoolSize = 8                                    // (4 x 2) + 0
    connectionTimeout = 2_000
    addDataSourceProperty("reWriteBatchedInserts", "true") // a batch becomes a few INSERTs
})

// 2. one transaction per chunk of 1,000 rows
fun import(rows: List<NewPayment>) = rows.chunked(1_000).forEach { chunk ->
    pool.connection.use { conn ->
        conn.autoCommit = false
        try {
            insertChunk(conn, chunk)                       // addBatch per row, one executeBatch
            conn.commit()
        } catch (e: SQLException) {
            conn.rollback()
            throw e
        }
    }
}

