fun saveAll(pool: DataSource, rows: List<Refund>) {
    pool.connection.use { conn ->                       // use: back to the pool on every path
        conn.autoCommit = false                         // one transaction for the whole batch
        try {
            conn.prepareStatement(
                "INSERT INTO refunds (payment_id, amount_minor, reason, created_at) VALUES (?, ?, ?, ?)",
            ).use { ps ->
                for (r in rows) {
                    ps.setLong(1, r.paymentId)
                    ps.setLong(2, r.amountMinor)
                    ps.setString(3, r.reason)           // values only, never pasted into the SQL
                    ps.setTimestamp(4, Timestamp.from(r.createdAt))
                    ps.addBatch()
                }
                ps.executeBatch()                       // a few round trips for the whole list
            }
            conn.commit()
        } catch (e: SQLException) {
            conn.rollback()
            throw e
        }
    }
}
// reWriteBatchedInserts=true (pgJDBC), e.g. addDataSourceProperty("reWriteBatchedInserts", "true")
